import{_ as t,c as e,o as p,ah as s,ao as a,ap as n}from"./chunks/framework.Dq2_gudl.js";const g=JSON.parse('{"title":"连一只麻雀，祂都记得——它从未被遗忘","description":"耶稣说，一只麻雀掉在地上，天父都知道。从马太福音与诗篇看神对动物的看顾，以及它的一生如何被珍视。","frontmatter":{"title":"连一只麻雀，祂都记得——它从未被遗忘","description":"耶稣说，一只麻雀掉在地上，天父都知道。从马太福音与诗篇看神对动物的看顾，以及它的一生如何被珍视。"},"headers":[],"relativePath":"zh/pets-in-heaven/not-one-sparrow-forgotten.md","filePath":"zh/pets-in-heaven/not-one-sparrow-forgotten.md"}'),r={name:"zh/pets-in-heaven/not-one-sparrow-forgotten.md"};function i(l,o,h,c,d,u){return p(),e("div",null,[...o[0]||(o[0]=[s('<div class="pl-quote"><p>「它只是一只小动物。世界会记得它吗？还是只有我一个人在怀念它？」</p><p class="pl-quote-soft">耶稣回答过这个问题，而祂的答案比我们想象的更温柔。</p></div><section class="pl-section"><h2>一、耶稣说：一只麻雀掉在地上，天父都知道</h2><blockquote><p><strong>马太福音 10:29-31</strong></p><p>&quot;Are not two sparrows sold for a farthing? and one of them shall not fall on the ground without your Father. But the very hairs of your head are all numbered. Fear ye not therefore, ye are of more value than many sparrows.&quot;</p></blockquote><p>在耶稣的时代，麻雀是最便宜的东西之一——两只卖一分银子。那是一种「没人会特别在意」的生命。</p><p>耶稣却说：<strong>如果没有你们的天父，一只也不会掉在地上。</strong></p><p>这句话里的「掉落」（fall），指的正是死亡。耶稣在说的就是：一只最便宜的小鸟死掉，都不是神不知道、不在意的意外。它的离世，在神那里是有记录、被看见的。</p><p>如果你的它是一只小小的、别人眼中「不过是动物」的同伴——这节经文就是为你写的。神连麻雀都记得，祂怎么会忘记你的它。</p></section><section class="pl-section"><h2>二、祂喂养它，一天都没有漏掉</h2><blockquote><p><strong>诗篇 147:9</strong></p><p>&quot;He giveth to the beast his food, and to the young ravens which cry.&quot;</p></blockquote><p>大卫在另一处也说：</p><blockquote><p><strong>诗篇 36:6</strong></p><p>&quot;…O LORD, thou preservest man and beast.&quot;</p></blockquote><p>「救护人和牲畜」——原文里「牲畜」就是野地与家中的动物。这句话把动物放在神看顾的名单里，不是顺便一提，而是并列。</p><p>这意味着什么？意味着你的它从出生到离开，每一餐、每一个冬天、每一次你不在家的时候，都有那位神在看顾。你以为你一个人在照顾它，其实你是在和神一起照顾它。</p></section><section class="pl-section"><h2>三、它属于神——这是最安心的部分</h2><blockquote><p><strong>诗篇 50:10-11</strong></p><p>&quot;For every beast of the forest is mine, and the cattle upon a thousand hills. I know all the fowls of the mountains: and the wild beasts of the field are mine.&quot;</p></blockquote><p>神说：「森林中的百兽是我的，千山上的牲畜也是我的。山中的飞鸟我都知道。」</p><p>你的它，从来不是你「拥有」的财产，而是神交给你照顾的礼物。而当礼物的主人收回去的时候，祂不是把它丢掉——祂是把它<strong>带回自己那里</strong>。</p><p>你不知道祂会怎么照顾它、它现在在哪里、它是否记得你的声音。但你知道那是谁的手：是那双连麻雀都数过的手。</p><p class="pl-quote-soft">如果你今天只能记住一句话，请记住这一句：</p></section><div class="pl-quote"><p>「它从来没有离开神的目光。现在也没有。」</p></div><section class="pl-section"><h2>可以试着这样祷告</h2><p>「主啊，谢谢祢把它交给我照顾了这些年。<br>谢谢祢在我不看见的地方也看顾它。<br>现在我不再把它抱在怀里了，但我知道祢的手比我更大。<br>求祢照顾它，就像祢照顾每一只麻雀一样。<br>也求祢照顾我，因为我很想它。阿们。」</p><p><a href="/zh/pets-in-heaven/">← 回到 Pets in Heaven</a> ｜ 下一篇：<a href="/zh/pets-in-heaven/rainbow-bridge-covenant">彩虹桥的那一端</a></p></section><div class="pl-cta"><h2>它有一个名字。</h2><p>在 PetLoss 里写下它的名字和一个它的小习惯——那些别人不知道、只有你知道的细节。它们值得被保存。</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">在 App Store 下载</a></div><div class="pl-bible"><h3>让圣经的话继续陪你</h3><p>文中引用的经文都出自圣经。用《彩虹圣经》随时阅读神的话、设置每日经文小组件，在想念它的日子里仍有一盏灯。</p><div class="pl-bible-shots"><figure><img src="'+a+'" alt="Rainbow Bible 圣经小组件显示 2 Timothy 2:13" loading="lazy"><figcaption>每日经文放在主屏幕</figcaption></figure><figure><img src="'+n+'" alt="Rainbow Bible App 的「天堂里的毛孩」主题，显示 Matthew 10:29-31" loading="lazy"><figcaption>切换到「天堂里的毛孩」主题读经</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">在 App Store 获取《彩虹圣经》</a></div>',8)])])}const b=t(r,[["render",i]]);export{g as __pageData,b as default};
